package pe.edu.grupo4.carga.entity;
import jakarta.persistence.*; import lombok.*; import pe.edu.grupo4.base.entity.*; import java.time.*;
@Entity @Table(name="cargas_academicas",indexes=@Index(columnList="docente_id,ciclo_academico,dia_semana")) @Getter @Setter @NoArgsConstructor
public class CargaAcademica { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="ciclo_academico",nullable=false,length=20) private String cicloAcademico; @ManyToOne(optional=false) @JoinColumn(name="docente_id") private Docente docente; @ManyToOne(optional=false) @JoinColumn(name="curso_id") private Curso curso; @Column(nullable=false,length=20) private String seccion; @ManyToOne(optional=false) @JoinColumn(name="sede_id") private Sede sede; @Enumerated(EnumType.STRING) @Column(name="dia_semana",nullable=false) private DayOfWeek diaSemana; @Column(name="hora_inicio",nullable=false) private LocalTime horaInicio; @Column(name="hora_fin",nullable=false) private LocalTime horaFin; @Enumerated(EnumType.STRING) @Column(nullable=false) private EstadoCarga estado=EstadoCarga.ACTIVA; public enum EstadoCarga { ACTIVA, ANULADA } }
